/**
 * NR-13 is the authored bridge for the upper-primary and junior-secondary
 * coverage trough. English is stored as ENGLISH here because the historical
 * coverage audit tracks it separately from the LITERACY alias. Its authority
 * remains the Liberia MOE Language Arts curriculum and the existing LR-LIT
 * authority records.
 */
export const NR13_VERSION = "nr13-2026.1";
export const NR13_TARGET_LESSONS = 15;
export const NR13_LESSON_QUIZ_COUNT = 5;
export const NR13_UNIT_QUIZ_COUNT = 10;
export const NR13_TERM_EXAM_COUNT = 30;
export const NR13_GRADES = [5, 6, 7, 8] as const;
export const NR13_SUBJECTS = ["MATH", "ENGLISH", "SCIENCE", "SOCIAL_STUDIES", "CIVICS"] as const;
export type Nr13Subject = (typeof NR13_SUBJECTS)[number];

export type Nr13AuthorityRecord = {
  code: string;
  grade: number;
  subject: Nr13Subject;
  strand: string;
  description: string;
  sourceFile: string;
  sourcePages: string;
  sourceArchive: string;
  sourceSha256?: string;
  sourceUrl?: string;
  evidenceStatus: "REPO_STANDARD" | "VERIFIED_MOE_OBJECTIVE";
};

type Topic = {
  unitTitle: string;
  strand: string;
  concept: string;
  standardCodes: string[];
  objective: string;
  vocabulary: string[];
  examples: [string, string];
  guidedPractice: string;
  independentPractice: string;
  misconception: string;
  correction: string;
  extension: string;
  materials: string[];
  skillArea?: string;
};

type AssessmentItem = {
  id: string;
  type: "mcq";
  standardCode: string;
  concept: string;
  prompt: string;
  options: string[];
  correctIndex: number;
  answerKey: string;
  explanation: string;
  points: number;
};

export type Nr13GenerationRecord = {
  contentId: string;
  grade: number;
  subject: string;
  canonicalSubject: Nr13Subject;
  contentType: "lesson";
  status: "generated";
  version: string;
  hash: string;
  unitId: string;
  orderInUnit: number;
  lessonType: "core";
  payload: Record<string, unknown>;
};

