const standard = (code: string, grade: number, subject: Nr13Subject, strand: string, description: string): Nr13AuthorityRecord => ({
  code, grade, subject, strand, description, sourceFile: REPO, sourcePages: "seed record", sourceArchive: "repository curriculum authority", evidenceStatus: "REPO_STANDARD",
});

const social = (grade: number, unit: number, strand: string, description: string, pages: string): Nr13AuthorityRecord => ({
  code: `MOE.2011.G${grade}.SOCIAL_STUDIES.U${unit}`,
  grade,
  subject: "SOCIAL_STUDIES",
  strand,
  description,
  sourceFile: grade <= 6 ? "Social Studies Grade 1-6.pdf" : "Social Studies 7-9.pdf",
  sourcePages: pages,
  sourceArchive: grade <= 6 ? G16 : G79,
  sourceSha256: grade <= 6 ? G16_SHA : "89b1f263f6cd238d4e1c9b31897f85a2ca7cdcece5c78f21ed72f1b8262849bb",
  sourceUrl: grade <= 6 ? G16_URL : G79_URL,
  evidenceStatus: "VERIFIED_MOE_OBJECTIVE",
});

