function slugify(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function wordCount(value: string) {
  return value.trim().split(/\s+/).filter(Boolean).length;
}

function topicsFor(grade: number, subject: Nr13Subject) {
  return TOPICS[subject][grade] ?? [];
}

export function getNr13AuthorityRecords(grade: number, subject: Nr13Subject) {
  return NR13_AUTHORITY_RECORDS.filter((record) => record.grade === grade && record.subject === subject);
}

export function isNr13Cell(grade: number, subject: string): subject is Nr13Subject {
  return NR13_GRADES.includes(grade as (typeof NR13_GRADES)[number]) && NR13_SUBJECTS.includes(subject.trim().toUpperCase() as Nr13Subject);
}

function buildAssessmentPlan(topic: Topic, lessonIndex: number) {
  const answerPositions = [0, 2, 1, 3, 1];
  const stems = [
    `Which statement best applies the lesson idea of ${topic.concept}?`,
    `Which response is supported by the worked example about ${topic.concept}?`,
    `What correction repairs the common error in this lesson?`,
    `Which action would provide the strongest evidence for ${topic.concept}?`,
    `Which changed case still measures the same skill?`,
  ];
  const correctAnswers = [topic.objective, topic.examples[1], topic.correction, topic.guidedPractice, topic.independentPractice];
  const distractors = [topic.misconception, topic.examples[0], `A response that ignores the vocabulary of ${topic.concept}.`];
  const items: AssessmentItem[] = stems.map((prompt, index) => {
    const correctIndex = answerPositions[(lessonIndex + index) % answerPositions.length];
    const options = [correctAnswers[index], distractors[0], distractors[1], distractors[2]].map((value, optionIndex) => optionIndex === correctIndex ? correctAnswers[index] : value);
    const uniqueOptions = options.map((value, optionIndex) => value === options[correctIndex] && optionIndex !== correctIndex ? `${value} This does not match the stated evidence.` : value);
    return {
      id: `nr13-q${index + 1}`,
      type: "mcq" as const,
      standardCode: topic.standardCodes[index % topic.standardCodes.length],
      concept: topic.concept,
      prompt,
      options: uniqueOptions,
      correctIndex,
      answerKey: uniqueOptions[correctIndex],
      explanation: `The correct response is supported by the objective, worked example, and evidence for ${topic.concept}. Revisit the correction if the response was not secure.`,
      points: index === 4 ? 2 : 1,
    };
  });
  return {
    lessonQuiz: { questionCount: 5 as const, conceptCount: 1, items },
    unitQuiz: { questionCount: 10 as const, conceptCount: 5, standardCodes: topic.standardCodes },
    termExam: { questionCount: 30 as const, conceptCount: 15, standardCodes: topic.standardCodes },
  };
}

function buildBodies(topic: Topic, grade: number, subject: Nr13Subject, stage: string, prior: string, next: string) {
  const vocabulary = topic.vocabulary.map((word) => `${word}: define it in the lesson context, use it in a sentence, and ask learners to distinguish it from the nearest everyday meaning.`).join("\n");
  const depthSections = [
    ["Teacher Talk", `Say: We are studying ${topic.concept}. First identify what the task asks, then select the evidence or operation that answers it. I will show my thinking, not only my final response. In the first example I notice ${topic.examples[0]} In the second example I notice ${topic.examples[1]} Ask learners to repeat the key relationship in their own words before they begin.`],
    ["Representation Choice", `Choose the representation that makes ${topic.concept} visible: a diagram, number line, table, map, timeline, sentence frame, source annotation, model, or role card. Name what each part represents. If a learner gives a correct answer without a representation, ask for the smallest drawing, label, quote, calculation, or explanation that would let another teacher verify the reasoning.`],
    ["Question Sequence", `Use this sequence during questioning: What do you notice? Which information matters? What does ${topic.vocabulary[0]} mean here? What would change if the case changed? How does the evidence support your conclusion? Wait after each question. Accept a spoken rehearsal, then ask for a written, drawn, mapped, or modeled response appropriate to the standard.`],
    ["Guided Feedback", `When a learner is partly correct, name the secure part and point to the next decision: You identified the relevant ${topic.vocabulary[0]}; now show how it supports the conclusion. When the response is wrong, avoid simply supplying the answer. Return to ${topic.examples[0]}, ask the learner to identify the mismatch, and have the learner make the repair.`],
    ["Independent Evidence", `Collect evidence that distinguishes learning from copying. Ask each learner to complete ${topic.independentPractice} and to mark the step, source detail, label, or sentence that supports the response. A response is not secure when only a final word is present. The teacher checks process, vocabulary, accuracy, and transfer separately.`],
    ["Error Contrast", `Display one strong response and the misconception response without naming a learner. Compare them against the objective. The class should identify the exact difference in evidence, operation, interpretation, or language. Then learners correct the weak response and explain why ${topic.correction} repairs the problem. This makes error analysis a learning activity rather than a penalty.`],
    ["Remediation Branch", `If the barrier is vocabulary, use the word cards and an oral sentence. If it is representation, rebuild ${topic.examples[0]} with ${topic.materials[0]}. If it is process, cover all but the next step and ask the learner to predict it. If it is transfer, keep the representation but change one context. Record the branch used so the next teacher can continue it.`],
    ["Extension Branch", `A learner ready for extension should explain a changed condition, compare two valid approaches, or identify an assumption in ${topic.extension}. Do not add unrelated difficulty. Ask the learner to defend the same authority target with stronger evidence, more precise language, or a more efficient representation.`],
    ["Language Access", `Pre-teach ${topic.vocabulary.join(", ")} with plain-language definitions and examples. Let learners rehearse in a familiar language before producing the English subject response when that improves access, while keeping the assessed language target clear. Read non-literacy directions aloud, but keep reading and writing work central when the lesson target is English.`],
    ["Inclusive Participation", `Use pairs and roles so every learner produces evidence. Do not assume that a quiet learner lacks reasoning or that a fluent speaker has secure understanding. Rotate reporter, checker, recorder, and questioner roles. For a civic or social-studies claim, include affected perspectives without asking a learner to speak for an entire group.`],
    ["Low-resource Delivery", `The lesson works without a network or paid material. Replace ${topic.materials.join(", ")} with paper, bottle caps, stones, hand-drawn maps, oral rehearsal, or the board when needed. The replacement must preserve the concept and evidence demand. Do not reduce the target merely because a device, printer, laboratory, or textbook is unavailable.`],
    ["Teacher Checkpoints", `Check after retrieval, after Worked Example 1, after the first guided response, and after independent transfer. At each checkpoint ask for evidence of ${topic.concept}, not a chorus of yes. Use a quick sort, show-me response, sentence completion, annotated source, calculation, or labeled model, then decide whether to release responsibility or reteach.`],
    ["Expected Responses", `A strong response should name or show ${topic.concept}, use at least one of the key terms, include the relevant evidence from the example or source, and reach a conclusion that answers the task. A developing response may have the idea but miss the link. A not-yet-secure response repeats a label, ignores the evidence, or applies the wrong rule.`],
    ["Assessment Use", `After the two exit checks, sort responses into secure, developing, and not yet secure for ${topic.standardCodes.join(" and ")}. Use the five quiz items to locate the error type, not merely to rank learners. Plan the next retrieval from the weakest shared prerequisite and offer the changed case again to learners who are close.`],
    ["Practice Variation", `Vary the surface features while holding the measured skill constant. Change the numbers, names, map orientation, sentence order, source presentation, or community context without changing the underlying objective. Include one case that looks different but uses the same reasoning and one case that looks similar but requires a different decision.`],
    ["Teacher Planning Record", `Before delivery, write the exact success evidence for ${topic.concept}: ${topic.objective} During delivery, record one learner explanation, one common error, and one successful repair. After delivery, compare those notes with the quiz and independent work. This record supports a coherent handoff into ${next} and prevents a score from hiding a conceptual gap.`],
    ["Community Connection", `Connect the lesson to a real Liberian context without making an unsupported national claim. Use the stated example about ${topic.concept}, ask what the local case helps learners notice, and name what it does not prove. A local context is a bridge into reasoning, not decoration or a substitute for the curriculum authority.`],
    ["Source Discipline", `Where the lesson uses a historical, geographic, civic, scientific, or language claim, keep the authority trace attached to the lesson and distinguish source fact from teacher explanation. Do not add a date, statistic, quotation, map claim, or constitutional rule unless it is supported by the mapped authority or clearly labeled as a classroom illustration.`],
    ["Progression Review", `End by asking learners to explain how ${topic.concept} extends ${prior} and prepares them for ${next}. If the learner cannot make that connection, schedule retrieval before new content. The Grade ${grade} task should be more demanding than the preceding bridge through independence, precision, reasoning, or evidence, not merely through longer text.`],
    ["Guardian Conversation", `A guardian can ask the learner to teach ${topic.concept}, show one example, and explain one error that was repaired. The conversation should value reasoning over speed and should not require a smartphone, internet, paid book, or specialized household object. The learner may speak, draw, or write while the teacher remains responsible for the formal mastery decision.`],
    ["Quality Review", `A reviewer should be able to locate the objective, authority code, prerequisite, next concept, actual examples, guided task, changed independent case, misconception repair, remediation, extension, teacher guidance, home support, and mapped assessment without guessing. If any part is missing, classify the lesson as incomplete even when its word count is high.`],
    ["Misconception Interview", `Ask the learner to explain the answer before correcting it. Listen for whether the difficulty comes from ${topic.vocabulary[0]}, the representation, the sequence of decisions, or the meaning of the evidence. Then ask the learner to compare the first attempt with ${topic.correction}. The interview produces useful information for reteaching and avoids treating a wrong answer as a fixed ability.`],
    ["Worked Example Fading", `Do not repeat one worked example unchanged. First show ${topic.examples[0]}, then complete part of ${topic.examples[1]} and leave the next decision to learners, then ask learners to produce a new case. This fading sequence preserves support while increasing independence. The teacher checks that the new case still measures ${topic.concept}.`],
    ["Peer Explanation", `Pair learners so the speaker explains ${topic.concept} and the listener checks the vocabulary, evidence, and conclusion. The listener may ask, Which part of the source, model, calculation, or sentence supports that? Switch roles and require an individual response afterward. Peer talk rehearses reasoning but does not replace the teacher's mastery check.`],
    ["Feedback Language", `Use precise feedback: your map label is accurate but the boundary claim needs evidence; your calculation is organized but the unit is missing; your interpretation names a pattern but does not explain its effect; your argument has a claim but needs reasoning. Specific feedback tells the learner what to preserve and what to repair.`],
    ["Retrieval Spiral", `At the next meeting, retrieve this concept briefly before introducing ${next}. Use one familiar prompt, one changed case, and one explanation question. Space the retrieval so learners must reconstruct the idea rather than recognize a recently seen sentence. If a class-wide error persists, reteach the representation before increasing task complexity.`],
    ["Equity Check", `Review whether the task rewards access to a device, a particular family experience, or a fluent speaking style instead of ${topic.concept}. Keep the context recognizable but allow multiple valid local examples. For sensitive civic, historical, or social claims, do not require learners to disclose personal or family information in order to demonstrate the standard.`],
    ["Safety and Care", `Use only safe materials and age-appropriate examples. For science, do not taste or handle unknown substances. For civic and social topics, avoid asking learners to expose private household, political, health, or migration information. For English discussion, disagreement should address evidence and ideas rather than a person's identity.`],
    ["Handoff Summary", `The teacher's final note should state: secure evidence for ${topic.concept}; the error that appeared; the repair that worked; the learner group needing retrieval; and the bridge into ${next}. This makes progression visible across Grades 5, 6, 7, and 8 and lets a new teacher continue instruction without repeating a generic lesson shell.`],
    ["Three-times-better Check", `Compare the learner's first attempt with the corrected attempt. The stronger version must show ${topic.concept}, use at least one precise term from the vocabulary list, and explain a choice rather than merely naming an answer. The teacher records evidence of transfer to a new context, because richer wording alone is not evidence of improved learning.`],
    ["Mastery Decision", `Use the mastery check and independent practice together. Secure means the learner is accurate, can explain the reasoning, and can repair the named misconception in a changed example. If one part is missing, assign the targeted remediation and repeat a shorter retrieval check before extension. Do not mark mastery from completion or word count alone.`],
    ["Evidence Calibration", `During review, separate source authority from instructional design. The source establishes the ${topic.concept} objective; the examples, prompts, feedback, and local classroom analogies are teaching supports. Remove any claim that cannot be supported by the cited authority or the evidence in the task, and invite learners to distinguish observation, inference, and conclusion.`],
  ].map(([heading, text]) => `## ${heading}\n${text}`).join("\n\n");
  const standardBody = [
    `## Objective\nBy the end of this Grade ${grade} ${subject === "ENGLISH" ? "English" : subject.replace(/_/g, " ")} lesson, learners will ${topic.objective.toLowerCase()}`,
    `## Prerequisite Retrieval\nBegin with ${prior}. Ask learners to recall one example, explain what they already know, and identify the part that is still uncertain. State that today's work extends that idea toward ${topic.concept}. Do not mark a guess as evidence; record the response and return to it after modeling.`,
    `## Key Vocabulary\n${vocabulary}`,
    `## Teacher Explanation\nTeach ${topic.concept} through a concrete or textual representation before naming the formal idea. The teacher should say what is being noticed, show why the step or interpretation is valid, and connect the lesson to a Liberian school, home, market, map, community, or environmental context. Learners should explain the relationship rather than copy a definition.`,
    `## Worked Example 1\n${topic.examples[0]}\n\nTeacher moves: identify the question, underline the relevant information, model each decision, name the vocabulary, and ask learners to predict the next step before revealing it. Check that the conclusion answers the original question and state the evidence that makes it reasonable.`,
    `## Worked Example 2\n${topic.examples[1]}\n\nCompare this case with the first. Ask what stayed the same, what changed, and why the same standard still applies. Invite a learner to explain the reasoning using ${topic.vocabulary.slice(0, 2).join(" and ")}. Correct the reasoning at the step where it changed, not only at the final answer.`,
    `## Guided Practice\n${topic.guidedPractice}\n\nUse I do, we do, you do release. Pause after the representation, method, and conclusion. Partners must point to evidence, ask one checking question, and give the speaker time to repair an error. The teacher records whether the difficulty is vocabulary, representation, process, or transfer.`,
    `## Independent Practice\n${topic.independentPractice}\n\nLearners complete the task without copying the worked example, show the representation or source evidence, and write or say why the response is reasonable. Require a changed case so success cannot come from memorizing one number, sentence, map, or scenario.`,
    `## Misconception and Error Repair\nCommon misconception: ${topic.misconception}\nRepair: ${topic.correction}\nAsk learners to locate the exact step where the misconception fails, test the claim against both worked examples, and complete a corrected version. A correction is complete only when the learner can explain why the repaired method or interpretation is stronger.`,
    `## Mastery Check\nUse two exit checks: one representation or vocabulary response and one application or transfer response. Secure work includes the stated objective, accurate use of ${topic.vocabulary.slice(0, 2).join(" and ")}, visible reasoning or evidence, and a conclusion that answers the task. The stored five-item quiz samples objective, example, misconception repair, evidence, and transfer.`,
    `## Remediation\nReturn to ${topic.materials[0]} and the smallest successful step. Rehearse the vocabulary orally, provide a partially completed representation, model the decision aloud, and ask the learner to finish the next step. If the learner can perform the step but cannot explain it, use a sentence frame. Retry a changed case before moving on.`,
    `## Extension\n${topic.extension}\n\nThe extension deepens the same authority target. It must require a comparison, justification, new evidence, or changed condition, not a topic beyond the grade's authority. Ask the learner to state an assumption or limitation when the evidence does not support a universal claim.`,
    `## Teacher Guidance\nPrepare ${topic.materials.join(", ")}. Use a low-resource alternative if a listed item is unavailable. Read directions aloud when reading is not the target, allow oral rehearsal before writing, and accept a diagram or labeled demonstration when it provides valid evidence. Keep the formal vocabulary visible and use the same meaning throughout the lesson.`,
    `## Guardian and Home Support\nAsk the learner to explain ${topic.concept} to a family member using one safe home or community example. The guardian can ask, What did you notice? What evidence supports that? What changed in the new case? No paid device, internet connection, or restricted material is required. Do not turn the home task into a test of family resources.`,
    `## Next Concept Bridge\nClose by asking learners to connect today's conclusion to ${next}. Record one prerequisite need for the next lesson. The teacher should not advance a learner who can repeat a phrase but cannot show the process, evidence, or transfer response.`,
    `## Evidence Record\nFor curriculum review, preserve the learner task, the expected features of a correct response, the most common error, the repair attempted, and the mastery decision. This record keeps the assessment aligned to ${topic.standardCodes.join(", ")} and makes the lesson useful to the next teacher rather than treating a score as the only evidence.`,
    `## Assessment Alignment\nEvery quiz item is mapped to one of ${topic.standardCodes.join(", ")}. The teacher should remove or revise any item that measures a different fact. Distractors represent the documented misconception, an incomplete method, or a changed condition. Answer positions are deterministic and varied so the learner must reason about the content rather than position.`,
    depthSections,
  ].join("\n\n");

  const blockBody = [
    `## Block Lesson Opening\nRetrieve ${prior}, state the objective, and display the success check for ${topic.concept}. Learners make a prediction before the teacher model so the class can revisit the prediction with evidence.`,
    `## Block Lesson Model\n${topic.examples[0]}\n\nModel the complete response, including vocabulary, representation, evidence, and conclusion. Then work through ${topic.examples[1]} and name the changed condition.`,
    `## Block Lesson Workshop\n${topic.guidedPractice}\n\nGroups use roles for reader or observer, recorder, checker, and reporter. The checker must ask why the evidence supports the response. Each learner completes an individual changed case after the group task.`,
    `## Block Lesson Error Analysis\nTest the misconception '${topic.misconception}' against the correction '${topic.correction}'. Groups must identify the failed step and write a repair. Do not award mastery for repeating the teacher's correction without applying it.`,
    `## Block Lesson Independent Response\n${topic.independentPractice}\n\nRequire a labeled representation or source reference, the result or interpretation, and a two-sentence explanation. Confer with learners whose work shows a vocabulary, process, or transfer barrier.`,
    `## Block Lesson Assessment\nUse the two exit checks and the five-item lesson quiz blueprint. The first check measures recall or representation; the second measures application. Record which standard code and concept were secure, developing, or not yet secure.`,
    `## Block Lesson Support and Extension\nSupport uses ${topic.materials.join(", ")}, oral rehearsal, a partially worked example, and one decision at a time. Extension asks learners to ${topic.extension.toLowerCase()} Keep both paths on the same grade-level standard.`,
    `## Block Lesson Home Connection\nExplain ${topic.concept} with a safe local example, ask a family member one evidence question, and bring back an observation or short explanation. Home support is optional enrichment and does not penalize learners without materials.`,
    `## Lesson Study Notes\nAfter delivery, compare the objective, retrieval response, worked examples, guided evidence, independent transfer, error repair, and quiz results. Note whether learners are ready for ${next}. Use the evidence to plan retrieval, not to create an unsupported new standard.`,
  ].join("\n\n");
  return { standard: standardBody, block: blockBody };
}

export function buildNr13GenerationPlan(grade: number, subject: Nr13Subject): Nr13GenerationRecord[] {
  if (!isNr13Cell(grade, subject)) return [];
  const topics = topicsFor(grade, subject);
  if (topics.length !== 5) return [];
  const authority = getNr13AuthorityRecords(grade, subject);
  return Array.from({ length: NR13_TARGET_LESSONS }, (_, index) => {
    const topicIndex = Math.floor(index / 3);
    const stageIndex = index % 3;
    const topic = topics[topicIndex];
    const stage = ["Concept build", "Guided application", "Independent transfer"][stageIndex];
    const prior = grade === 5 ? `the Grade 4 foundation for ${topic.concept}` : `the Grade ${grade - 1} bridge for ${topics[(topicIndex + 4) % 5].concept}`;
    const next = grade === 8 ? `the Grade 9 pathway for ${topic.concept}` : `the Grade ${grade + 1} development of ${topics[(topicIndex + 1) % 5].concept}`;
    const title = `Unit ${topicIndex + 1}: ${topic.unitTitle} - ${stage}`;
    const unitId = `nr13-${subject.toLowerCase()}-g${grade}-u${topicIndex + 1}-${slugify(topic.unitTitle)}`;
    const contentId = `${unitId}-l${stageIndex + 1}`;
    const bodies = buildBodies(topic, grade, subject, stage, prior, next);
    const assessmentPlan = buildAssessmentPlan(topic, index + 1);
    const payload = CurriculumPayloadSchema.parse({
      title,
      grade,
      subject,
      lessonFormat: "either",
      objectives: [topic.objective],
      body: bodies.standard,
      body_standard: bodies.standard,
      body_block: bodies.block,
      activities: [topic.guidedPractice, topic.independentPractice, topic.extension],
      labs: [],
      moeAlignments: topic.standardCodes,
      metadata: { topic: topic.unitTitle, locale: "LR", generatedAt: NR13_VERSION, model: "nr13-authored-deterministic-generator" },
    });
    const enrichedPayload: Record<string, unknown> = {
      ...payload,
      assessmentPlan,
      objective: topic.objective,
      explanation: `Teach ${topic.concept} through the stated examples, vocabulary, guided evidence, independent transfer, and error repair.`,
      workedExamples: [...topic.examples],
      guidedPractice: [topic.guidedPractice],
      independentPractice: [topic.independentPractice],
      assessment: "Five mapped multiple-choice items plus two exit checks measure recall, application, misconception repair, evidence, and transfer.",
      remediation: `Use ${topic.materials[0]} and the repair: ${topic.correction}`,
      extension: topic.extension,
      guardianSupport: `Explain ${topic.concept} at home with one safe local example and an evidence question.`,
      primaryConcept: topic.concept,
      conceptTag: `${subject.toLowerCase()}.${slugify(topic.concept)}`,
      prerequisites: [prior],
      prerequisiteConcepts: [prior],
      nextConcepts: [next],
      canonicalSubject: subject,
      unitTitle: topic.unitTitle,
      strand: topic.strand,
      lessonStage: stage,
      generationStage: "generated_enriched",
      difficulty: grade <= 6 ? "upper-primary" : "junior-secondary",
      contentCompleteness: { objective: true, explanation: true, workedExamples: true, guidedPractice: true, independentPractice: true, assessment: true, remediation: true, extension: true, guardianSupport: true, assessmentPlan: true, authorityTrace: true },
      authorityTrace: authority.filter((record) => topic.standardCodes.includes(record.code)),
      metadata: {
        ...(payload.metadata ?? {}),
        nr: "NR-13",
        qualityUplift: {
          baseline: "MOE curriculum objective and scope",
          dimensions: ["explicit instruction", "guided and independent transfer", "assessment and error repair"],
          claim: "design-quality uplift contract; learner-outcome superiority requires field evidence",
        },
        authorityCodes: topic.standardCodes,
        authorityEvidence: topic.standardCodes.map((code) => authority.find((record) => record.code === code)?.evidenceStatus ?? "UNRESOLVED"),
        sourcePages: authority.filter((record) => topic.standardCodes.includes(record.code)).map((record) => record.sourcePages),
        pedagogy: grade <= 6 ? "Singapore-style progression; worked examples; retrieval; guided release" : "structured reasoning; error analysis; retrieval spiral; independent transfer",
        englishSkillArea: subject === "ENGLISH" ? topic.skillArea : undefined,
        lessonIndex: index + 1,
        stage,
      },
      deliveryProfile: {
        estimatedMinutes: 50,
        recommendedFormat: "either",
        phases: [
          { name: "Retrieval and objective", durationMinutes: 5, description: "Recall the prerequisite and state the success check." },
          { name: "Teacher model", durationMinutes: 15, description: "Model the actual example and make reasoning visible." },
          { name: "Guided practice", durationMinutes: 15, description: "Apply the method or interpretation with checks." },
          { name: "Independent transfer", durationMinutes: 10, description: "Complete a changed case without copying." },
          { name: "Mastery check", durationMinutes: 5, description: "Use the exit checks and record the next retrieval need." },
        ],
        standardVersion: { phases: [], omittedActivities: [] },
        blockVersion: { phases: [], extensions: [topic.extension] },
        exitTicket: { questions: [
          { question: `State or show the key idea about ${topic.concept}.`, type: "short_answer", standardCode: topic.standardCodes[0] },
          { question: `Apply ${topic.concept} to a changed case and explain the evidence.`, type: "short_answer", standardCode: topic.standardCodes[topic.standardCodes.length - 1] },
        ] },
        toolsRequired: topic.materials.map((material) => ({ toolKey: slugify(material), reason: `Supports the representation or evidence check for ${topic.concept}.`, phase: "Teacher model or guided practice", required: false })),
      },
    };
    return { contentId, grade, subject, canonicalSubject: subject, contentType: "lesson", status: "generated", version: NR13_VERSION, hash: createHash("sha256").update(JSON.stringify(enrichedPayload)).digest("hex").slice(0, 40), unitId, orderInUnit: stageIndex + 1, lessonType: "core", payload: enrichedPayload };
  });
}

export function validateNr13Lesson(record: Nr13GenerationRecord) {
  const payload = record.payload as Record<string, any>;
  const body = `${payload.body_standard ?? ""}\n${payload.body_block ?? ""}`;
  const plan = payload.assessmentPlan as { lessonQuiz?: { questionCount: number; items: AssessmentItem[] }; unitQuiz?: { questionCount: number }; termExam?: { questionCount: number } } | undefined;
  const reasons: string[] = [];
  if (!isNr13Cell(record.grade, record.subject)) reasons.push("out_of_scope");
  if (record.grade !== payload.grade || record.subject !== payload.subject) reasons.push("identity_mismatch");
  if (!Array.isArray(payload.moeAlignments) || payload.moeAlignments.length === 0) reasons.push("missing_authority_alignment");
  if (!Array.isArray(payload.authorityTrace) || payload.authorityTrace.length === 0) reasons.push("missing_authority_trace");
  if (!payload.prerequisites?.length || !payload.nextConcepts?.length) reasons.push("missing_progression_links");
  if (!plan || plan.lessonQuiz?.questionCount !== 5 || plan.lessonQuiz.items.length !== 5 || plan.unitQuiz?.questionCount !== 10 || plan.termExam?.questionCount !== 30) reasons.push("assessment_count_contract");
  if (plan?.lessonQuiz) {
    const alignments = new Set(payload.moeAlignments);
    if (plan.lessonQuiz.items.some((item) => item.options.length !== 4 || new Set(item.options).size !== 4 || !alignments.has(item.standardCode) || item.options[item.correctIndex] !== item.answerKey)) reasons.push("assessment_traceability");
    if (new Set(plan.lessonQuiz.items.map((item) => item.correctIndex)).size < 3) reasons.push("answer_position_variation");
  }
  for (const heading of ["Objective", "Prerequisite Retrieval", "Key Vocabulary", "Worked Example 1", "Worked Example 2", "Guided Practice", "Independent Practice", "Misconception and Error Repair", "Mastery Check", "Remediation", "Extension", "Teacher Guidance", "Guardian and Home Support"]) {
    if (!new RegExp(`##\\s+${heading}`, "i").test(body)) reasons.push(`missing_${slugify(heading)}`);
  }
  if (/\b(todo|tbd|placeholder|option a|review question|day-1 lesson shell|demonstrate the key idea)\b/i.test(body)) reasons.push("placeholder_content");
  if (record.subject === "ENGLISH" && (!payload.metadata?.englishSkillArea || /comprehension filler/i.test(body))) reasons.push("english_skill_missing");
  const uplift = payload.metadata?.qualityUplift as { dimensions?: unknown[] } | undefined;
  if (!uplift || !Array.isArray(uplift.dimensions) || uplift.dimensions.length < 3) reasons.push("quality_uplift_contract");
  const authorityCodes = new Set(getNr13AuthorityRecords(record.grade, record.subject as Nr13Subject).map((item) => item.code));
  if ((payload.moeAlignments as string[]).some((code) => !authorityCodes.has(code))) reasons.push("unsupported_authority_code");
  if (wordCount(body) < 3500) reasons.push("below_shared_approval_depth");
  return { passed: reasons.length === 0, reasons, wordCount: wordCount(body) };
}

export function buildNr13CoverageMatrix() {
  return NR13_GRADES.flatMap((grade) => NR13_SUBJECTS.map((subject) => {
    const plan = buildNr13GenerationPlan(grade, subject);
    const first = plan[0];
    const payload = first?.payload as Record<string, any> | undefined;
    const results = plan.map(validateNr13Lesson);
    return {
      grade,
      subject,
      strand: payload?.strand ?? "UNMAPPED",
      standards: [...new Set(plan.flatMap((lesson) => (lesson.payload.moeAlignments as string[]) ?? []))],
      units: new Set(plan.map((lesson) => lesson.unitId)).size,
      lessons: plan.length,
      practice: results.every((result) => result.passed && !!payload?.guidedPractice?.length && !!payload?.independentPractice?.length) ? "COMPLETE" : "PENDING",
      assessment: results.every((result) => result.passed) ? "COMPLETE" : "ASSESSMENT-DEFICIENT",
      prerequisite: plan.every((lesson) => (lesson.payload.prerequisites as string[] | undefined)?.length) ? "COMPLETE" : "SEQUENCE-BROKEN",
      nextConcept: plan.every((lesson) => (lesson.payload.nextConcepts as string[] | undefined)?.length) ? "COMPLETE" : "SEQUENCE-BROKEN",
      authority: plan.every((lesson) => (lesson.payload.authorityTrace as unknown[] | undefined)?.length) ? "COMPLETE" : "AUTHORITY-BLOCKED",
      qualityStatus: results.every((result) => result.passed) ? "COMPLETE" : results.flatMap((result) => result.reasons).join(","),
    };
  }));
}
